// ValidationError 是稳定的结构化校验错误;Path 指向首个失败位置。
type ValidationError struct {
	Path    string
	Rule    string
	Message string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("%s: %s (%s)", e.Path, e.Message, e.Rule)
}

func validationError(path, rule, format string, args ...any) error {
	return &ValidationError{Path: path, Rule: rule, Message: fmt.Sprintf(format, args...)}
}

// ValidateFrameSize 按完整 UTF-8 帧字节数执行硬上限;maxBytes<=0 时使用契约默认值。
func ValidateFrameSize(frame []byte, maxBytes int64) error {
	if maxBytes <= 0 {
		maxBytes = DefaultMaxMsgBytes
	}
	if int64(len(frame)) > maxBytes {
		return validationError("$", "maxBytes", "帧为 %d 字节,上限 %d", len(frame), maxBytes)
	}
	return nil
}

// ValidateKindBody 校验已知字段并忽略未知加法字段;cmd/event/error/report 还会下钻语义 schema。
func ValidateKindBody(kind Kind, raw json.RawMessage) error {
	name, ok := bodySchemas[kind]
	if !ok {
		return validationError("$", "kind", "未知 kind %q", kind)
	}
	if err := validateRaw(name, raw); err != nil {
		return err
	}
	switch kind {
	case KindHello:
		return validateWitnessAdvertisement(raw, true)
	case KindPing:
		return validateWitnessAdvertisement(raw, false)
	case KindCmd:
		var body CmdBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		if err := validateCommandSemantics(body); err != nil {
			return err
		}
		return rebaseValidationError(ValidatePrimitiveArgs(body.Name, body.Ver, body.Args), "$.args")
	case KindEvent:
		var body EventBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		return rebaseValidationError(ValidateEventData(string(body.Name), body.Data), "$.data")
	case KindAck:
		var body AckBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		return validateErrorData(body.Error)
	case KindResult:
		var body ResultBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		return validateErrorData(body.Error)
	case KindReport:
		var body ReportBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		return validateReportSemantics(body)
	default:
		return nil
	}
}

// ValidateSchema 校验 contract.schemas.types 中任一具名 DTO；供 witness 持久记录读回时使用。
func ValidateSchema(name string, raw json.RawMessage) error {
	if err := validateRaw(name, raw); err != nil {
		return err
	}
	switch name {
	case "JournalEntry":
		var entry JournalEntry
		if err := json.Unmarshal(raw, &entry); err != nil {
			return validationError("$", "json", "%v", err)
		}
		if entry.Result != nil && entry.Result.Ref != entry.Ref {
			return validationError("$.result.ref", "correlation", "journal result.ref 必须等于 journal.ref")
		}
		if entry.ExpiresAt <= entry.StartedAt {
			return validationError("$.expiresAt", "ordering", "journal expiresAt 必须晚于 startedAt")
		}
	case "OutboxEntry":
		var entry OutboxEntry
		if err := json.Unmarshal(raw, &entry); err != nil {
			return validationError("$", "json", "%v", err)
		}
		if entry.ExpiresAt <= entry.CreatedAt {
			return validationError("$.expiresAt", "ordering", "outbox expiresAt 必须晚于 createdAt")
		}
	}
	return nil
}

func ValidatePrimitiveArgs(name string, ver int, raw json.RawMessage) error {
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	return validateRaw(s.Args, raw)
}

func ValidatePrimitiveData(name string, ver int, raw json.RawMessage) error {
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	return validateRaw(s.Data, raw)
}

func ValidatePrimitiveGuards(name string, ver int, raw json.RawMessage) error {
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	if s.Guards == "" {
		if len(raw) == 0 || bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
			return nil
		}
		return validationError("$", "forbidden", "原语 %q 未声明 guardsSchema", name)
	}
	if len(raw) == 0 || bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return validationError("$", "required", "原语 %q 必须携带 guards", name)
	}
	return validateRaw(s.Guards, raw)
}

// ValidatePrimitiveEvidence 把 evidenceSchema 解释为每个 evidence item 的 schema；真实 SX 至少一项。
func ValidatePrimitiveEvidence(name string, ver int, raw json.RawMessage) error {
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	if s.Evidence == "" {
		return nil
	}
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return validationError("$", "type", "evidence 需要 array:%v", err)
	}
	if len(items) == 0 {
		return validationError("$", "minItems", "真实 effectful ok 至少一项 evidence")
	}
	for i, item := range items {
		if err := validateRaw(s.Evidence, item); err != nil {
			return rebaseValidationError(err, fmt.Sprintf("$[%d]", i))
		}
	}
	return nil
}

// ValidatePrimitiveResult 同时强制 result 基础形态、ok data、真实 SX evidence、failed.sideEffect 及错误码允许集合。
func ValidatePrimitiveResult(name string, ver int, raw json.RawMessage) error {
	if err := ValidateKindBody(KindResult, raw); err != nil {
		return err
	}
	s, ok := primitiveSchemas[name]
	if !ok {
		return validationError("$", "primitive", "原语 %q 无激活 schema", name)
	}
	if ver != s.Ver {
		return validationError("$", "version", "原语 %q 需要版本 %d,收到 %d", name, s.Ver, ver)
	}
	var body ResultBody
	if err := json.Unmarshal(raw, &body); err != nil {
		return validationError("$", "json", "%v", err)
	}
	if body.Status == ResultStatusOk {
		if err := rebaseValidationError(ValidatePrimitiveData(name, ver, body.Data), "$.data"); err != nil {
			return err
		}
		evidenceRaw, err := json.Marshal(body.Evidence)
		if err != nil {
			return validationError("$.evidence", "json", "%v", err)
		}
		return rebaseValidationError(ValidatePrimitiveEvidence(name, ver, evidenceRaw), "$.evidence")
	}
	if body.Status == ResultStatusFailed && s.Class == "effectful" && (body.Error == nil || body.Error.SideEffect == "") {
		return validationError("$.error.sideEffect", "required", "effectful failed 必须显式标注 sideEffect")
	}
	if body.Status == ResultStatusFailed && body.Error != nil && body.Error.SideEffect != "" {
		meta, ok := ErrorCodes[body.Error.Code]
		if !ok {
			return validationError("$.error.code", "enum", "未知错误码 %q", body.Error.Code)
		}
		allowed := false
		for _, sideEffect := range meta.SideEffect {
			if sideEffect == body.Error.SideEffect {
				allowed = true
				break
			}
		}
		if !allowed {
			return validationError("$.error.sideEffect", "errorCodeSideEffect", "错误码 %s 不允许 sideEffect=%s", body.Error.Code, body.Error.SideEffect)
		}
	}
	return nil
}

func ValidateEventData(name string, raw json.RawMessage) error {
	s, ok := eventSchemas[name]
	if !ok {
		return validationError("$", "event", "未知事件 %q", name)
	}
	return validateRaw(s, raw)
}

func validateCommandSemantics(body CmdBody) error {
	meta, ok := Primitives[body.Name]
	if !ok || meta.Ver == 0 {
		return validationError("$.name", "primitive", "未知或未激活原语 %q", body.Name)
	}
	if meta.Ver != body.Ver {
		return validationError("$.ver", "version", "原语 %q 需要版本 %d,收到 %d", body.Name, meta.Ver, body.Ver)
	}
	isDebug := strings.HasPrefix(body.Name, "debug.")
	if !isDebug && body.Context == nil && !meta.ContextOptionalBeforeBinding {
		return validationError("$.context", "required", "除绑定前探测外,非 debug 原语必须携带 context")
	}
	if meta.Class == ClassEffectful {
		if body.IdemKey == "" {
			return validationError("$.idemKey", "required", "effectful 原语必须携带 idemKey")
		}
	} else if body.IdemKey != "" {
		return validationError("$.idemKey", "forbidden", "readonly/intrusive 原语禁止携带 idemKey")
	}
	if meta.LeaseMs > 0 && body.LeaseMs == 0 {
		return validationError("$.leaseMs", "required", "原语 %q 必须携带租约", body.Name)
	}
	if meta.LeaseMs == 0 && body.LeaseMs != 0 {
		return validationError("$.leaseMs", "forbidden", "原语 %q 未启用租约", body.Name)
	}
	if !isDebug && meta.Class != ClassReadonly {
		if body.Context == nil || body.Context.ExpectedPrincipalFingerprint == "" {
			return validationError("$.context.expectedPrincipalFingerprint", "required", "intrusive/effectful 原语必须携带期望账号指纹")
		}
	}
	if err := rebaseValidationError(ValidatePrimitiveGuards(body.Name, body.Ver, body.Guards), "$.guards"); err != nil {
		return err
	}
	return nil
}

func validateWitnessAdvertisement(raw json.RawMessage, hello bool) error {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(raw, &fields); err != nil {
		return validationError("$", "json", "%v", err)
	}
	names := []string{"witnessStoreId", "outboxPending", "journalOpen"}
	present := 0
	for _, name := range names {
		if _, ok := fields[name]; ok {
			present++
		}
	}
	required := false
	if hello {
		var body HelloBody
		if err := json.Unmarshal(raw, &body); err != nil {
			return validationError("$", "json", "%v", err)
		}
		for _, feature := range body.Features {
			if feature == string(FeatureWitness1) {
				required = true
			}
		}
	}
	if required && present != len(names) {
		return validationError("$", "witnessAdvertisement", "声明 witness/1 时三个证词字段必须齐备")
	}
	if present != 0 && present != len(names) {
		return validationError("$", "witnessAdvertisement", "证词诊断字段必须全有或全无")
	}
	return nil
}

func validateErrorData(body *ErrorBody) error {
	if body == nil {
		return nil
	}
	meta, ok := ErrorCodes[body.Code]
	if !ok || meta.DataSchema == "" {
		return nil
	}
	if len(body.Data) == 0 || bytes.Equal(bytes.TrimSpace(body.Data), []byte("null")) {
		return validationError("$.error.data", "required", "错误 %s 必须携带专用 data", body.Code)
	}
	return rebaseValidationError(ValidateSchema(meta.DataSchema, body.Data), "$.error.data")
}

func validateReportSemantics(body ReportBody) error {
	if body.Result != nil && body.Result.Ref != body.Ref {
		return validationError("$.result.ref", "correlation", "done result.ref 必须等于 report.ref")
	}
	if body.Journal != nil && body.Journal.Ref != body.Ref {
		return validationError("$.journal.ref", "correlation", "journal.ref 必须等于 report.ref")
	}
	switch body.State {
	case ReportStateAttempting:
		if body.Journal == nil || body.Journal.State != JournalStateAttempting {
			return validationError("$.journal.state", "state", "attempting report 必须携带 attempting journal")
		}
	case ReportStateDone:
		if body.Result == nil || body.Journal == nil || body.Journal.State != JournalStateCommitted {
			return validationError("$.journal.state", "state", "done report 必须携带 committed journal 与完整 result")
		}
	}
	return nil
}

func validateRaw(schemaName string, raw json.RawMessage) error {
	if len(raw) == 0 {
		return validationError("$", "json", "空 JSON")
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var value any
	if err := dec.Decode(&value); err != nil {
		return validationError("$", "json", "%v", err)
	}
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		return validationError("$", "json", "JSON 后存在额外内容")
	}
	spec, ok := schemaTypes[schemaName]
	if !ok {
		return validationError("$", "schema", "未知 schema %q", schemaName)
	}
	return validateSpec(spec, value, "$")
}

func validateSpec(spec schemaSpec, value any, path string) error {
	if value == nil {
		if spec.Nullable || spec.Type == "any" {
			return nil
		}
		return validationError(path, "nullable", "不允许 null")
	}
	if spec.Ref != "" {
		target, ok := schemaTypes[spec.Ref]
		if !ok {
			return validationError(path, "schema", "未知引用 %q", spec.Ref)
		}
		return validateSpec(target, value, path)
	}
	if spec.MaxJSONBytes > 0 {
		encoded, err := json.Marshal(value)
		if err != nil {
			return validationError(path, "json", "%v", err)
		}
		if len(encoded) > spec.MaxJSONBytes {
			return validationError(path, "maxJsonBytes", "JSON 为 %d 字节,上限 %d", len(encoded), spec.MaxJSONBytes)
		}
	}
	switch spec.Type {
	case "any":
		return nil
	case "boolean":
		v, ok := value.(bool)
		if !ok {
			return validationError(path, "type", "需要 boolean")
		}
		if spec.Const != nil && v != *spec.Const {
			return validationError(path, "const", "必须为 %t", *spec.Const)
		}
		return nil
	case "string":
		v, ok := value.(string)
		if !ok {
			return validationError(path, "type", "需要 string")
		}
		runes := utf8.RuneCountInString(v)
		if runes < spec.MinLength {
			return validationError(path, "minLength", "长度 %d 小于下限 %d", runes, spec.MinLength)
		}
		if spec.MaxLength > 0 && runes > spec.MaxLength {
			return validationError(path, "maxLength", "长度 %d 超过上限 %d", runes, spec.MaxLength)
		}
		if spec.MaxBytes > 0 && len([]byte(v)) > spec.MaxBytes {
			return validationError(path, "maxBytes", "UTF-8 为 %d 字节,上限 %d", len([]byte(v)), spec.MaxBytes)
		}
		if spec.EnumRef != "" && !stringAllowed(schemaEnums[spec.EnumRef], v) {
			return validationError(path, "enum", "%q 不在 %s 内", v, spec.EnumRef)
		}
		return nil
	case "int", "int64":
		n, ok := value.(json.Number)
		if !ok {
			return validationError(path, "type", "需要整数")
		}
		v, err := n.Int64()
		if err != nil {
			return validationError(path, "type", "需要 int64 范围内整数")
		}
		if v < -9007199254740991 || v > 9007199254740991 {
			return validationError(path, "safeInteger", "整数超出跨 Go/TS 安全范围")
		}
		if spec.Minimum != nil && v < *spec.Minimum {
			return validationError(path, "minimum", "%d 小于下限 %d", v, *spec.Minimum)
		}
		if spec.Maximum != nil && v > *spec.Maximum {
			return validationError(path, "maximum", "%d 超过上限 %d", v, *spec.Maximum)
		}
		return nil
	case "array":
		v, ok := value.([]any)
		if !ok {
			return validationError(path, "type", "需要 array")
		}
		if len(v) < spec.MinItems {
			return validationError(path, "minItems", "元素数 %d 小于下限 %d", len(v), spec.MinItems)
		}
		if spec.MaxItems > 0 && len(v) > spec.MaxItems {
			return validationError(path, "maxItems", "元素数 %d 超过上限 %d", len(v), spec.MaxItems)
		}
		if spec.Items == nil {
			return validationError(path, "schema", "array 缺 items")
		}
		seen := make(map[string]struct{}, len(v))
		for i, item := range v {
			if err := validateSpec(*spec.Items, item, fmt.Sprintf("%s[%d]", path, i)); err != nil {
				return err
			}
			if spec.UniqueItems {
				encoded, err := json.Marshal(item)
				if err != nil {
					return validationError(fmt.Sprintf("%s[%d]", path, i), "uniqueItems", "元素无法规范编码")
				}
				key := string(encoded)
				if _, duplicate := seen[key]; duplicate {
					return validationError(fmt.Sprintf("%s[%d]", path, i), "uniqueItems", "数组元素必须唯一")
				}
				seen[key] = struct{}{}
			}
		}
		return nil
	case "object":
		v, ok := value.(map[string]any)
		if !ok {
			return validationError(path, "type", "需要 object")
		}
		for name, field := range spec.Fields {
			fv, exists := v[name]
			if !exists {
				if !field.Optional {
					return validationError(path+"."+name, "required", "缺少必填字段")
				}
				continue
			}
			if err := validateSpec(field, fv, path+"."+name); err != nil {
				return err
			}
		}
		// 未知字段故意不遍历:主版本内 must-ignore。
		for _, rule := range spec.Rules {
			if err := validateSchemaRule(rule, v, path); err != nil {
				return err
			}
		}
		return nil
	default:
		return validationError(path, "schema", "未知 schema type %q", spec.Type)
	}
}

func validateSchemaRule(rule schemaRule, values map[string]any, path string) error {
	actual, ok := values[rule.WhenField]
	if !ok || !anyAllowed(rule.Equals, actual) {
		return nil
	}
	nonNull := func(field string) bool { value, exists := values[field]; return exists && value != nil }
	switch rule.Kind {
	case "requiredWhen":
		if !nonNull(rule.Field) {
			return validationError(path+"."+rule.Field, "requiredWhen", "条件成立时字段必填且非 null")
		}
	case "forbiddenWhen":
		if nonNull(rule.Field) {
			return validationError(path+"."+rule.Field, "forbiddenWhen", "条件成立时字段必须缺省或 null")
		}
	case "exactlyOneWhen":
		count := 0
		for _, field := range rule.Fields {
			if nonNull(field) {
				count++
			}
		}
		if count != 1 {
			return validationError(path, "exactlyOneWhen", "条件成立时 %v 必须恰有一个非 null", rule.Fields)
		}
	case "atLeastOneTrueWhen":
		matched := false
		for _, field := range rule.Fields {
			if value, ok := values[field].(bool); ok && value {
				matched = true
			}
		}
		if !matched {
			return validationError(path, "atLeastOneTrueWhen", "条件成立时 %v 至少一个必须为 true", rule.Fields)
		}
	case "allFalseWhen":
		for _, field := range rule.Fields {
			if value, ok := values[field].(bool); !ok || value {
				return validationError(path+"."+field, "allFalseWhen", "条件成立时必须为 false")
			}
		}
	case "lessThanOrEqualWhen":
		if len(rule.Fields) != 2 {
			return validationError(path, "schema", "lessThanOrEqualWhen 需要两个字段")
		}
		left, leftOK := values[rule.Fields[0]].(json.Number)
		right, rightOK := values[rule.Fields[1]].(json.Number)
		if !leftOK || !rightOK {
			return nil
		}
		leftValue, leftErr := left.Int64()
		rightValue, rightErr := right.Int64()
		if leftErr != nil || rightErr != nil {
			return validationError(path, "schema", "lessThanOrEqualWhen 字段必须是整数")
		}
		if leftValue > rightValue {
			return validationError(path+"."+rule.Fields[1], "lessThanOrEqualWhen", "%s 必须不小于 %s", rule.Fields[1], rule.Fields[0])
		}
	default:
		return validationError(path, "schema", "未知规则 %q", rule.Kind)
	}
	return nil
}

func stringAllowed(values []string, value string) bool {
	for _, candidate := range values {
		if candidate == value {
			return true
		}
	}
	return false
}

func anyAllowed(values []any, value any) bool {
	for _, candidate := range values {
		if reflect.DeepEqual(candidate, value) {
			return true
		}
	}
	return false
}

func rebaseValidationError(err error, base string) error {
	if err == nil {
		return nil
	}
	var validation *ValidationError
	if !errorsAsValidation(err, &validation) {
		return err
	}
	path := base
	if validation.Path != "$" {
		path += strings.TrimPrefix(validation.Path, "$")
	}
	return &ValidationError{Path: path, Rule: validation.Rule, Message: validation.Message}
}

func errorsAsValidation(err error, target **ValidationError) bool {
	validation, ok := err.(*ValidationError)
	if ok {
		*target = validation
	}
	return ok
}
